declare(strict_types=1);require __DIR__.'/app/marketplace-transaction.php';$user=require_verified();$id=marketplace_text($_GET,'id',36,true);$view=(string)($_GET['view']??'overview');$allowedViews=['overview','agreement','payment','premobilization','mobilization','active','return','activity'];if(!in_array($view,$allowedViews,true))$view='overview';
try{$transaction=marketplace_transaction($user,$id);$agreement=marketplace_transaction_agreement($user,$id);$agreementVersion=$agreement?rows('SELECT * FROM marketplace_agreement_versions WHERE agreement_id=? AND version_number=?',[$agreement['id'],$agreement['current_version']])[0]??null:null;$signatures=$agreement?rows('SELECT s.*,o.name organization_name FROM marketplace_agreement_signatures s JOIN owners o ON o.id=s.organization_id WHERE s.agreement_id=? ORDER BY s.signed_at',[$agreement['id']]):[];$payments=rows('SELECT * FROM marketplace_payments WHERE transaction_id=? ORDER BY created_at',[$id]);$escrow=rows('SELECT * FROM marketplace_escrow_records WHERE transaction_id=? ORDER BY created_at DESC LIMIT 1',[$id])[0]??null;$insurance=rows('SELECT * FROM marketplace_insurance_records WHERE transaction_id=? ORDER BY created_at DESC',[$id]);$gate=marketplace_premobilization_gate($user,$id);$handovers=$transaction['lease_id']?rows('SELECT * FROM marketplace_handover_records WHERE lease_id=? ORDER BY completed_at',[$transaction['lease_id']]):[];$activity=rows('SELECT a.*,u.full_name FROM marketplace_transaction_activity a LEFT JOIN users u ON u.id=a.actor_user_id WHERE a.transaction_id=? ORDER BY a.created_at DESC,a.id DESC',[$id]);$pageTitle='Transaction · '.$transaction['equipment_name'];}
