<nav class="transaction-tabs" aria-label="Transaction workspace"><?php foreach(['overview'=>'Overview','agreement'=>'Agreement','payment'=>'Payment','premobilization'=>'Premobilization','mobilization'=>'Mobilization','active'=>'Active Lease','return'=>'Return','activity'=>'Activity'] as $key=>$label):?><a href="marketplace-transaction?id=<?= e($id) ?>&amp;view=<?= $key ?>" <?= $view===$key?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach;?></nav>
