<?php elseif($view==='agreement'):?><section class="transaction-panel"><header><div><h2>Agreement</h2><p>Generated from the frozen accepted offer. Every revision is retained.</p></div><form action="marketplace-transaction-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="agreement.generate"><input type="hidden" name="transaction_id" value="<?= e($id) ?>"><input type="hidden" name="return_view" value="agreement"><button class="secondary-button"><?= $agreement?'Create revision':'Generate agreement' ?></button></form></header><?php if($agreement):?><p><strong>Status:</strong> <?= e($agreement['status']) ?> · Version <?= (int)$agreement['current_version'] ?></p><pre class="agreement-body"><?= e($agreementVersion['body']??'') ?></pre><div class="agreement-actions"><?php if(in_array($agreement['status'],['DRAFT','REVIEW'],true)):?><form action="marketplace-transaction-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="agreement.send"><input type="hidden" name="transaction_id" value="<?= e($id) ?>"><input type="hidden" name="return_view" value="agreement"><button class="market-button">Send for signature</button></form><?php endif;?><?php if(in_array($agreement['status'],['SENT','PARTIALLY_SIGNED'],true)):?><form action="marketplace-transaction-action" method="post" class="signature-form"><?= csrf_field() ?><input type="hidden" name="action" value="agreement.sign"><input type="hidden" name="transaction_id" value="<?= e($id) ?>"><input type="hidden" name="return_view" value="agreement"><label>Authorized signer<input name="signer_name" value="<?= e($user['full_name']) ?>" required></label><label class="confirm"><input type="checkbox" name="confirm_signature" value="1" required> I am authorized to sign this binding agreement.</label><button class="market-button">Sign agreement</button></form><?php endif;?></div><div class="signature-list"><?php foreach($signatures as $signature):?><p>✓ <?= e($signature['organization_name'].' · '.$signature['signer_name'].' · '.$signature['signed_at']) ?></p><?php endforeach;?></div><?php else:?><p>No agreement generated yet.</p><?php endif;?></section>
