e="1" required> Return condition captured</label><label>Evidence<input type="file" name="evidence" accept="image/jpeg,image/png,image/webp,video/mp4"></label><label>Owner signature<input name="owner_signature" required></label><label>Customer signature<input name="customer_signature" required></label><label class="full">Notes<textarea name="notes"></textarea></label><button class="market-button">Complete return inspection</button></form><?php elseif($transaction['status']==='INSPECTION'):?><form action="marketplace-transaction-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="transaction.complete"><input type="hidden" name="transaction_id" value="<?= e($id) ?>"><input type="hidden" name="return_view" value="return"><button class="market-button">Complete settlement</button></form><?php endif;?></section>
